        lastSnapshot?: SessionSnapshot<State>;
        store?: SessionStore<State>;
        abortSignal?: AbortSignal;
        onEndTurn?: (snapshotId?: string, finishReason?: AgentFinishReason) => void;
        onDetach?: (snapshotId: string) => void;
    });
